// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.prank(actor);
        bool ok = true;
        try c.setOwner(actor) { ok = true; } catch { ok = false; }
        assertTrue(actor == address(this) || !ok, "non-admin caller must revert");
    }
}
